import numpy as np
import pandas as pd

# Check if genes are in var_names
print("Available tumor/immune markers in dataset:")
tumor_markers = ['GFAP', 'S100B', 'OLIG2', 'SOX2', 'AQP4', 'VIM', 'EGFR', 'PDGFRA']
immune_markers = ['CD68', 'CD163', 'P2RY12', 'CX3CR1', 'LYZ', 'CSF1R', 'CD45', 'AIF1', 'TYROBP']

all_markers = []
for marker in tumor_markers + immune_markers:
    if marker in adata.var_names:
        all_markers.append(marker)

print(f"Found {len(all_markers)} markers: {all_markers}")

# Get mean expression per cluster for these markers
marker_expr = {}
for marker in all_markers:
    idx = np.where(adata.var_names == marker)[0][0]
    for cluster in ['0', '3', '12', '18']:
        mask = adata.obs['leiden'] == cluster
        expr = adata[mask].X.toarray().flatten()[idx] if hasattr(adata[mask].X, 'toarray') else adata[mask].X.A.flatten()[idx]
        mean_expr = np.mean(expr)
        if marker not in marker_expr:
            marker_expr[marker] = {}
        marker_expr[marker][cluster] = mean_expr

# Print as table
print("\nMarker expression (mean log-normalized):")
print("Marker".ljust(12), end="")
for c in ['0', '3', '12', '18']:
    print(f"{c:>10}", end="")
print()

